from __future__ import annotations

from fastapi.responses import HTMLResponse

from app.build_info import APP_VERSION, BUILD_ID


def reachability_page() -> HTMLResponse:
    return HTMLResponse(f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>NCT · Reachability</title>
<style>
:root{{--bg:#08141d;--panel:#0f1d27;--line:#294553;--text:#e7eef8;--muted:#9eb0b8;--accent:#57d6bf;--blue:#73bfff;--good:#61d095;--warn:#f4c95d;--bad:#ff7b7b;color-scheme:dark}}*{{box-sizing:border-box}}body{{margin:0;background:linear-gradient(135deg,#08141d,#10242e);color:var(--text);font:14px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}}header,main{{max-width:1180px;margin:auto}}header{{position:sticky;top:0;z-index:100;padding:16px 0 14px;border-bottom:1px solid var(--line);background:rgba(8,20,29,.97);backdrop-filter:blur(14px)}}.sr-only{{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}}.nct-brand{{display:flex;width:max-content;flex-direction:column;align-items:center;margin:0 auto;line-height:1;text-align:center}}.nct-brand>strong{{padding-left:.24em;font-size:40px;letter-spacing:.24em}}.nct-brand span{{margin-top:3px;padding-top:3px;border-top:1px solid var(--accent);color:var(--muted);font-size:9px;font-weight:650;letter-spacing:.09em;text-transform:uppercase;white-space:nowrap}}.nct-brand span b{{color:var(--accent);font-size:1.16em;font-weight:950}}.nav{{display:flex;justify-content:center;gap:8px;margin-top:8px;flex-wrap:wrap}}.nav a{{border:1px solid #315264;background:#142d38;color:#b9cadc;border-radius:7px;padding:6px 13px;text-decoration:none;font-weight:700}}.nav a.active{{background:var(--accent);border-color:var(--accent);color:#07171b}}main{{padding:24px 0 60px}}h2{{margin:0 0 7px;font-size:20px}}h3{{margin:0 0 6px;font-size:15px}}p{{margin:5px 0}}.panel{{background:rgba(15,29,39,.95);border:1px solid var(--line);border-radius:12px;padding:18px;margin-bottom:18px;box-shadow:0 10px 35px #0003}}.query{{display:grid;grid-template-columns:1.2fr 1.2fr .55fr .55fr auto;gap:10px;align-items:end}}label{{display:block;color:#bed0da;font-size:12px;font-weight:750;margin:4px 0 5px}}input,select{{width:100%;background:#0b1520;color:var(--text);border:1px solid #365268;border-radius:8px;padding:10px 11px;font:inherit}}button{{border:1px solid #3b6f91;background:#174665;color:#fff;border-radius:7px;padding:10px 15px;font:inherit;font-weight:800;cursor:pointer}}button:disabled{{opacity:.5;cursor:not-allowed}}.hint,.meta,.empty{{color:var(--muted)}}.status{{min-height:22px;margin-top:10px;color:var(--muted)}}.status.good{{color:var(--good)}}.status.bad{{color:var(--bad)}}.status.warn{{color:var(--warn)}}.hidden{{display:none!important}}.result-head{{display:flex;gap:14px;align-items:start;justify-content:space-between}}.outcome{{font-size:26px;font-weight:900}}.outcome.local,.outcome.allowed{{color:var(--good)}}.outcome.routed{{color:var(--blue)}}.outcome.blocked{{color:var(--bad)}}.outcome.unknown{{color:var(--warn)}}.chip{{display:inline-block;border-radius:999px;padding:3px 8px;background:#243f4d;color:#cce1ea;font-size:11px;font-weight:750}}.two{{display:grid;grid-template-columns:1.25fr .75fr;gap:18px}}.path{{display:flex;align-items:stretch;gap:8px;overflow:auto;margin-top:14px;padding-top:12px;border-top:1px solid var(--line)}}.path-step{{min-width:150px;flex:1;background:#0a1720;border:1px solid #315264;border-radius:8px;padding:9px 10px}}.path-step strong{{display:block}}.path-arrow{{display:grid;place-items:center;color:var(--accent);font-size:20px;font-weight:900}}.evidence{{border-left:4px solid var(--blue);background:#0a1720;border-radius:7px;padding:10px 12px;margin:8px 0}}.evidence.policy{{border-left-color:var(--good)}}.evidence.service{{border-left-color:var(--accent)}}.evidence strong{{display:block}}ul{{margin:8px 0;padding-left:20px}}.legend{{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}}.legend div{{background:#0a1720;border:1px solid var(--line);border-radius:8px;padding:10px}}.footer{{color:var(--muted);font-size:12px}}code{{color:#9edcff}}@media(max-width:1200px){{header,main{{padding-left:4vw;padding-right:4vw}}}}@media(max-width:850px){{.query,.two,.legend{{grid-template-columns:1fr}}.path{{flex-direction:column}}.path-arrow{{transform:rotate(90deg)}}}}
</style><script src="/assets/nct-session.js" defer></script></head><body>
<header><h1 class="sr-only">Reachability</h1><div class="nct-brand" aria-label="NCT, Network Characterization Tool"><strong>NCT</strong><span><b>N</b>etwork <b>C</b>haracterization <b>T</b>ool</span></div><nav class="nav" aria-label="Primary"><a href="/device-config">Device</a><a href="/scans">Nmap</a><a href="/analysis">Analyze</a><a href="/hunting">Hunt</a><a class="active" href="/reachability" aria-current="page">Reach</a><a href="/network-map">Map</a></nav></header>
<main><section class="panel"><h2>Reachability Analysis</h2><p class="hint">Evaluate what the retained routes, device policy, Saved Networks, and Nmap service evidence support. This page does not send network traffic.</p><div class="query"><div><label for="source">Source</label><input id="source" list="sourceOptions" placeholder="Host, subnet, or Internet"><datalist id="sourceOptions"></datalist></div><div><label for="destination">Destination</label><input id="destination" list="destinationOptions" placeholder="Host, subnet, or Internet"><datalist id="destinationOptions"></datalist></div><div><label for="protocol">Protocol</label><select id="protocol"><option value="tcp">TCP</option><option value="udp">UDP</option></select></div><div><label for="port">Port</label><input id="port" type="number" min="1" max="65535" value="443"></div><button id="evaluate">Evaluate</button></div><div id="status" class="status" role="status"></div></section>
<section id="result" class="hidden"><section class="panel"><div class="result-head"><div><div id="outcome" class="outcome"></div><p id="explanation"></p></div><span id="confidence" class="chip"></span></div><div id="path" class="path" aria-label="Likely path"></div></section><div class="two"><section class="panel"><h2>Evidence used</h2><div id="evidence"></div></section><section class="panel"><h2>Limits and uncertainty</h2><ul id="caveats"></ul></section></div></section>
<section class="panel"><h2>Outcome guide</h2><div class="legend"><div><h3>Local</h3><p class="meta">Both endpoints are in the same Saved Network. Local controls can still apply.</p></div><div><h3>Routed</h3><p class="meta">A retained route covers the destination, but policy is not established.</p></div><div><h3>Expected Allowed</h3><p class="meta">A supported explicit policy statement permits the exact service.</p></div><div><h3>Expected Blocked</h3><p class="meta">A supported explicit policy statement denies the exact service.</p></div><div><h3>Not Exposed</h3><p class="meta">Reserved for complete scan coverage that establishes the service was not exposed.</p></div><div><h3>Unknown</h3><p class="meta">The retained evidence cannot support an end-to-end conclusion.</p></div></div></section><div class="footer">Build <code>{APP_VERSION}</code> · <code>{BUILD_ID}</code></div></main>
<script>
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));
function setStatus(message,kind=''){{$('status').textContent=message;$('status').className='status '+kind}}
async function loadContext(){{try{{const response=await fetch('/api/reachability/context'),data=await response.json();if(!response.ok)throw new Error(data.detail||'Reachability evidence is unavailable');const networks=data.saved_networks||[],hosts=data.hosts||[];const options=['Internet',...networks.map(n=>n.cidr),...hosts.map(h=>h.ip)].filter(Boolean);const markup=options.map(value=>`<option value="${{esc(value)}}"></option>`).join('');$('sourceOptions').innerHTML=markup;$('destinationOptions').innerHTML=markup;setStatus(`${{networks.length}} Saved Network${{networks.length===1?'':'s'}}, ${{hosts.length}} observed host${{hosts.length===1?'':'s'}}, and ${{data.device_collections||0}} current device collection${{data.device_collections===1?'':'s'}} available.`,'good')}}catch(error){{setStatus(error.message,'bad')}}}}
function render(data){{$('result').classList.remove('hidden');const key=data.outcome.toLowerCase().replace('expected ','');$('outcome').textContent=data.outcome;$('outcome').className='outcome '+key;$('confidence').textContent=`${{data.confidence}} confidence`;$('explanation').textContent=data.explanation;$('path').innerHTML=(data.path||[]).map((item,index)=>`${{index?'<span class="path-arrow">→</span>':''}}<div class="path-step"><strong>${{esc(item.label)}}</strong><span class="meta">${{esc(item.detail||item.kind)}}</span></div>`).join('');$('evidence').innerHTML=(data.evidence||[]).map(item=>`<div class="evidence ${{esc(item.kind)}}"><strong>${{esc(item.title)}}</strong><span class="meta">${{esc(item.detail||'')}}</span>${{item.raw?`<br><code>${{esc(item.raw)}}</code>`:''}}</div>`).join('')||'<p class="empty">No supporting evidence matched this query.</p>';$('caveats').innerHTML=(data.caveats||[]).map(item=>`<li>${{esc(item)}}</li>`).join('')||'<li>No additional caveats were generated.</li>';}}
async function evaluate(){{const body={{source:$('source').value,destination:$('destination').value,protocol:$('protocol').value,port:Number($('port').value)}};setStatus('Evaluating retained evidence…');$('evaluate').disabled=true;try{{const response=await fetch('/api/reachability/evaluate',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(body)}}),data=await response.json();if(!response.ok)throw new Error(data.detail||'Evaluation failed');render(data);setStatus('Reachability evaluation complete.','good')}}catch(error){{setStatus(error.message,'bad')}}finally{{$('evaluate').disabled=false}}}}
$('evaluate').onclick=evaluate;loadContext();
</script></body></html>''')
